    /** 余液、现场选料和光谱值只在点击试算时参与计算，不形成额外快照协议。 */
    private MoltenIronBatchCalculationResultVo calculate(TbMoltenIronBatchAllocation allocation,
                                                          TbMoltenIronBatch batch,
                                                          MoltenIronBatchCalculationInput operatorInput) {
        CastingChargeRecipeManageGetVo recipeData = recipeService.get(batch.getRecipeId(), allocation.getTenantId());
        CastingChargeRecipeManageSaveDto calcInput = SerializationUtils.fromStr(
            SerializationUtils.toStr(recipeData), CastingChargeRecipeManageSaveDto.class);
        calcInput.setRecipeId(batch.getRecipeId());
        calcInput.setTotalMeltingMass(allocation.getAllocatedWeight());
        calcInput.setCalcStage(CALC_STAGE_MELTING);
        applyElementTargets(calcInput, operatorInput == null ? null : operatorInput.getElementTargets());
        applySelectedMaterials(calcInput, operatorInput, allocation);
        return recipeService.calcMoltenIronBatch(calcInput, allocation.getFurnaceId(),
            allocation.getRemainingMoltenIronWeight(),
            operatorInput == null ? Collections.emptyMap() : operatorInput.getResidualElements(),
            allocation.getTenantId(), allocation.getId());
    }

    private void applyElementTargets(CastingChargeRecipeManageSaveDto dto,
                                     List<MoltenIronBatchCalculationInput.ElementTarget> inputs) {
        Map<String, MoltenIronBatchCalculationInput.ElementTarget> inputByName =
            Optional.ofNullable(inputs).orElse(Collections.emptyList()).stream()
                .filter(input -> input != null && input.getName() != null)
                .collect(Collectors.toMap(MoltenIronBatchCalculationInput.ElementTarget::getName,
                    Function.identity(), (left, right) -> right));
        List<CastingChargeRecipeDataBo.ElementBound> constrainedTargets = new ArrayList<>();
        for (CastingChargeRecipeDataBo.ElementBound target :
            Optional.ofNullable(dto.getElementBounds()).orElse(Collections.emptyList())) {
            MoltenIronBatchCalculationInput.ElementTarget input = inputByName.get(target.getName());
            // 显式取消约束只影响当前配方内同名目标；null 和未传字段均保持旧客户端的默认约束语义。
            if (input != null && Boolean.FALSE.equals(input.getConstrained())) continue;
            if (input == null) {
                constrainedTargets.add(target);
                continue;
            }
            if (input.getMeltingLower() != null) target.setMeltingLower(input.getMeltingLower());
            if (input.getMeltingUpper() != null) target.setMeltingUpper(input.getMeltingUpper());
            if (input.getMeltingControl() != null) target.setMeltingControl(input.getMeltingControl());
            constrainedTargets.add(target);
        }
        // 配方外现场元素不会进入遍历，既不报错也不会扩大求解目标集合。
        dto.setElementBounds(constrainedTargets);
    }

    /** 页面选中的原料库物料就是本次候选集，库存不参与候选过滤和比例约束。 */
    private void applySelectedMaterials(CastingChargeRecipeManageSaveDto dto,
                                        MoltenIronBatchCalculationInput input,
                                        TbMoltenIronBatchAllocation allocation) {
        List<Long> selectedIds = Optional.ofNullable(input).map(MoltenIronBatchCalculationInput::getMaterials)
            .orElse(Collections.emptyList()).stream().map(MoltenIronBatchCalculationInput.Material::getMaterialId)
            .filter(Objects::nonNull).distinct().collect(Collectors.toList());
        if (selectedIds.isEmpty()) {
            throw new ServiceException("请从原料库选择本次试算物料");
        }
        // 配方级元素调整是计算快照，先按物料关联，后续候选料重建时恢复到对应炉料。
        Map<Long, CastingChargeRecipeDataBo.BatchingCharge> recipeChargeMap = Optional
            .ofNullable(dto.getBatchingResult()).map(CastingChargeRecipeManageSaveDto.BatchingResult::getCharges)
            .orElse(Collections.emptyList()).stream().filter(charge -> charge.getMaterialId() != null)
            .collect(Collectors.toMap(CastingChargeRecipeDataBo.BatchingCharge::getMaterialId,
                Function.identity(), (left, right) -> left));
        Map<Long, MaterialPoolMaterialElementVo> materialMap = materialPoolManageService
            .getCalculationMaterials(selectedIds, allocation.getTenantId()).stream()
            .collect(Collectors.toMap(MaterialPoolMaterialElementVo::getMaterialId, Function.identity(),
                (left, right) -> left));
        List<CastingChargeRecipeDataBo.BatchingCharge> charges = selectedIds.stream().map(materialId -> {
            MaterialPoolMaterialElementVo material = materialMap.get(materialId);
            if (material == null) {
                throw new ServiceException("所选原料不属于当前成分原料库：" + materialId);
            }
            // 候选料至少要有一项可计算元素，避免空成分原料进入求解器后产生伪有效结果。
            boolean hasElementContent = Optional.ofNullable(material.getElements()).orElse(Collections.emptyList())
                .stream().filter(Objects::nonNull)
                .anyMatch(element -> element.getElementName() != null
                    && (element.getContentFixed() != null || element.getContentMin() != null
                        || element.getContentMax() != null));
            if (!hasElementContent) {
                throw new ServiceException("所选原料未配置有效元素含量：" + material.getMaterialName());
            }
            CastingChargeRecipeDataBo.BatchingCharge charge = new CastingChargeRecipeDataBo.BatchingCharge();
            charge.setMaterialId(materialId);
            charge.setMaterialName(material.getMaterialName());
            // 试算结果会继续流入正式计划和点阵屏目标，别名与名称必须同时保留，历史空别名由下游展示回退名称。
            charge.setMaterialAlias(material.getMaterialAlias());
            charge.setMaterialPrice(Optional.ofNullable(material.getLatestUnitPrice()).orElse(BigDecimal.ZERO));
            charge.setIsMainCharge(1);
            charge.setIsInsideCharge(1);
            charge.setIsOutsideCharge(0);
            // 候选料基础数据以原料池为准；同物料的配方元素调整属于配方快照，重建时必须继续保留。
            Optional.ofNullable(recipeChargeMap.get(materialId))
                .map(CastingChargeRecipeDataBo.BatchingCharge::getMaterialElements)
