    Map<Long, Integer> indexByMaterialId = Optional.ofNullable(request.getMaterials())
        .orElse(Collections.emptyList()).stream()
        .collect(Collectors.toMap(ChargeBatchingCalcByConstrainPyRequest.Material::getMaterialId,
            ChargeBatchingCalcByConstrainPyRequest.Material::getIdx, (left, right) -> left));
    List<ChargeBatchingCalcByConstrainPyResponse.BatchingCharge> charges = Optional.ofNullable(furnace)
        .map(MoltenIronBatchRecipePyResponse.FurnaceResult::getCharges)
        .orElse(Collections.emptyList()).stream().map(source -> {
            ChargeBatchingCalcByConstrainPyResponse.BatchingCharge target =
                new ChargeBatchingCalcByConstrainPyResponse.BatchingCharge();
            Integer idx = indexByMaterialId.get(source.getMaterialId());
            target.setIdx(idx == null ? null : BigDecimal.valueOf(idx));
            target.setMeltingMass(source.getAdditionMass());
            return target;
        }).collect(Collectors.toList());
    adapted.setCharges(charges);
    adapted.setSumMeltingMass(charges.stream()
        .map(ChargeBatchingCalcByConstrainPyResponse.BatchingCharge::getMeltingMass)
        .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add));

    // 元素最终含量和实际发生的松弛区间适配为已有报告的结果与审计表结构。
    Map<String, MoltenIronBatchRecipePyResponse.ElementResult> furnaceElements = Optional.ofNullable(furnace)
        .map(MoltenIronBatchRecipePyResponse.FurnaceResult::getElements).orElse(Collections.emptyMap());
    adapted.setElements(furnaceElements.entrySet().stream().collect(Collectors.toMap(
        Map.Entry::getKey, entry -> {
            ChargeBatchingCalcByConstrainPyResponse.BatchingElement element =
                new ChargeBatchingCalcByConstrainPyResponse.BatchingElement();
            element.setMeltingContent(entry.getValue().getFinalContent());
            return element;
        })));
    adapted.setChargeInsideSlackDetails(furnaceElements.entrySet().stream()
        .filter(entry -> Boolean.TRUE.equals(entry.getValue().getTargetElement()))
        .filter(entry -> !Objects.equals(entry.getValue().getTargetLower(), entry.getValue().getEffectiveLower())
            || !Objects.equals(entry.getValue().getTargetUpper(), entry.getValue().getEffectiveUpper()))
        .collect(Collectors.toMap(Map.Entry::getKey, entry -> {
            MoltenIronBatchRecipePyResponse.ElementResult source = entry.getValue();
            ChargeBatchingCalcByConstrainPyResponse.SlackDetail detail =
                new ChargeBatchingCalcByConstrainPyResponse.SlackDetail();
            detail.setOriginalLower(source.getTargetLower());
            detail.setOriginalUpper(source.getTargetUpper());
            detail.setEffectiveLower(source.getEffectiveLower());
            detail.setEffectiveUpper(source.getEffectiveUpper());
            return detail;
        })));
    return buildCalcReport("# 铁水批次余液配料试算报告", dto, request, adapted, calcMsg);
}

/** 自动配方和铁水批次共用同一章节编排，只允许标题与响应适配不同。 */
private String buildCalcReport(String title,
                               CastingChargeRecipeManageSaveDto dto,
                               ChargeBatchingCalcByConstrainPyRequest request,
                               ChargeBatchingCalcByConstrainPyResponse response,
                               String calcMsg) {
    Map<String, ChargeBatchingCalcByConstrainPyRequest.ElementBound> bounds = request == null
        ? Collections.emptyMap() : Optional.ofNullable(request.getElementBoundsMelting()).orElse(Collections.emptyMap());
    Map<String, ChargeBatchingCalcByConstrainPyResponse.SlackDetail> relaxations = response == null
        ? Collections.emptyMap() : Optional.ofNullable(response.getChargeInsideSlackDetails()).orElse(Collections.emptyMap());
    boolean solved = response != null && CoreUtils.isTrue(response.getIsChargeInsideSolved());

item.stdout:
        vo.setCalcReportId(saveCalcReport(dto, request, response, vo.getCalcMsg(), currentDeptId));
        reportSaved = true;
        return vo;
    } catch (RuntimeException e) {
        // 参数校验和 Python 调用异常同样属于一次试算，必须留下可追溯的失败记录。
        if (!reportSaved) {
            String message = StringUtils.defaultIfBlank(e.getMessage(), "计算过程发生未识别异常");
            try {
                saveCalcReport(dto, request, response, "计算未完成：" + message, currentDeptId);
            } catch (RuntimeException reportException) {
                log.error("自动配料失败报告保存失败, recipeId={}", dto.getRecipeId(), reportException);
            }
        }
        throw e;
    }
}

/**
 * 自动配料按作业阶段分别试算。熔炼只求炉内主料；炉后/浇注以熔炼结果作为当前铁水继续调整。
 */
public CastingChargeRecipeManageAutoCalcVo calcAutoRecipeStage(CastingChargeRecipeManageSaveDto dto) {
    // 阶段试算与配方保存共用元素、原料校验，避免重复或空元素进入 Map 组装后抛运行时异常。
    castingChargeRecipeManageSupport.checkDto(dto);
    Long currentDeptId = atsiTenantService.getCurrentDeptId();
    if (Objects.equals(CALC_STAGE_MELTING, dto.getCalcStage())) {
        return calcMeltingStage(dto, currentDeptId);
    }
    if (Objects.equals(CALC_STAGE_OUTSIDE, dto.getCalcStage())) {
        return calcOutsideStage(dto, currentDeptId);
    }
    throw new ServiceException("请选择熔炼或炉后/浇注试算阶段");
}

/**
 * 铁水批次只计算一炉余液配料。Python 保留 N 炉能力，Java 按 allocation 单独试算并关联报告。
 */
public MoltenIronBatchCalculationResultVo calcMoltenIronBatch(
    CastingChargeRecipeManageSaveDto dto,
    String furnaceId,
    BigDecimal residualMass,
    Map<String, BigDecimal> residualElements,
    Long tenantId,
    Long moltenIronAllocationId
) {
    requireStageBaseData(dto);
    List<CastingChargeRecipeDataBo.BatchingCharge> charges = dto.getBatchingResult().getCharges();
    Map<String, ChargeBatchingCalcByConstrainPyRequest.ElementBound> bounds = dto.getElementBounds().stream()
        .map(this::toMeltingBound)
        .filter(ChargeBatchingCalcByConstrainPyRequest.ElementBound::isValidBound)
        .collect(Collectors.toMap(ChargeBatchingCalcByConstrainPyRequest.ElementBound::getName,
            Function.identity()));

    // 新入口固定成本最低、只算熔炼并开启元素松弛，其他配方制定入口保持原行为。
    AtomicInteger idx = new AtomicInteger();
    ChargeBatchingCalcByConstrainPyRequest request = new ChargeBatchingCalcByConstrainPyRequest();
    request.setParamId(String.format("[%s][%s][铁水批次]", dto.getRecipeName(), furnaceId));
    request.setRecipeId(dto.getRecipeId());
    request.setRecipeName(dto.getRecipeName());
    request.setStrategy(1);
    request.setLossModeFurnaceInside(Optional.ofNullable(dto.getLossModeFurnaceInside()).orElse(1));
    request.setEnableSlackVariable(true);
    request.setElementBoundsMelting(bounds);
    request.setMaterials(charges.stream()
        .map(charge -> toMeltingMaterial(charge, idx.getAndIncrement(), tenantId))
        .collect(Collectors.toList()));
    ChargeBatchingCalcByConstrainPyRequest.Furnace furnace = new ChargeBatchingCalcByConstrainPyRequest.Furnace();
    furnace.setFurnaceId(furnaceId);
    furnace.setFurnaceName(furnaceId);
    furnace.setResidualMass(Optional.ofNullable(residualMass).orElse(BigDecimal.ZERO));
    furnace.setResidualElements(Optional.ofNullable(residualElements).orElse(Collections.emptyMap()));
    furnace.setTargetMass(dto.getTotalMeltingMass());
    request.setFurnaces(Collections.singletonList(furnace));

    MoltenIronBatchRecipePyResponse response = pyComputationService.moltenIronBatchRecipe(request, tenantId);
    MoltenIronBatchRecipePyResponse.FurnaceResult furnaceResult = Optional.ofNullable(response)
        .map(MoltenIronBatchRecipePyResponse::getFurnaces)
        .filter(CollectionUtils::isNotEmpty).map(items -> items.get(0)).orElse(null);
    boolean solved = furnaceResult != null && Boolean.TRUE.equals(furnaceResult.getSolverSolved());
    String calcMsg = solved
        ? (Boolean.TRUE.equals(furnaceResult.getSlacked()) ? "铁水批次配料成功，已使用元素松弛" : "铁水批次配料成功")
        : Optional.ofNullable(furnaceResult).map(MoltenIronBatchRecipePyResponse.FurnaceResult::getDiagnostics)
            .filter(CollectionUtils::isNotEmpty).map(items -> String.join("；", items))
            .orElse("铁水批次配料计算服务无可用结果");
    Long reportId = saveCalcReport(dto, request, response, calcMsg, solved, null,
        buildMoltenIronCalcReport(dto, request, furnaceResult, calcMsg),
        tenantId, moltenIronAllocationId);
    if (!solved) {
        throw new ServiceException(calcMsg);
    }

    // Python 结果按物料 ID 回填现有计划加料结构，正式开炉无需理解算法内部模型。
    Map<Long, BigDecimal> resultMasses = furnaceResult.getCharges().stream().collect(Collectors.toMap(
        MoltenIronBatchRecipePyResponse.Charge::getMaterialId,
        MoltenIronBatchRecipePyResponse.Charge::getAdditionMass));
    charges.forEach(charge -> charge.setMeltingMass(resultMasses.getOrDefault(
        charge.getMaterialId(), BigDecimal.ZERO)));

    MoltenIronBatchCalculationResultVo output = new MoltenIronBatchCalculationResultVo();
    // 试算结果只持久化实际需要投料的正数物料；输入候选仍由 calculationInput 保留，便于用户重试或调整。
    output.setMaterials(charges.stream()
        .filter(charge -> charge != null
            && charge.getMeltingMass() != null
            && charge.getMeltingMass().signum() > 0)
        .collect(Collectors.toList()));
    output.setElementTargets(dto.getElementBounds());
    output.setElementContents(furnaceResult.getElements().entrySet().stream().collect(Collectors.toMap(
        Map.Entry::getKey, entry -> entry.getValue().getFinalContent())));
    // 数值 Map 保持旧契约；同名属性 Map 固化 Python 判定，页面无需再根据目标范围反推元素类型。
    output.setElementAttributes(furnaceResult.getElements().entrySet().stream().collect(Collectors.toMap(
        Map.Entry::getKey, entry -> {
            MoltenIronBatchCalculationResultVo.ElementAttribute attribute =
                new MoltenIronBatchCalculationResultVo.ElementAttribute();
            attribute.setIsTargetElement(Boolean.TRUE.equals(entry.getValue().getTargetElement()));
            attribute.setIsExtraElement(Boolean.TRUE.equals(entry.getValue().getExtraElement()));
            attribute.setElementStatus(entry.getValue().getElementStatus());
            return attribute;
        })));
    output.setSlacked(furnaceResult.getSlacked());
    output.setSlackTargets(furnaceResult.getElements().entrySet().stream()
        .filter(entry -> Boolean.TRUE.equals(entry.getValue().getTargetElement()))
        .filter(entry -> !Objects.equals(entry.getValue().getTargetLower(), entry.getValue().getEffectiveLower())
            || !Objects.equals(entry.getValue().getTargetUpper(), entry.getValue().getEffectiveUpper()))
        .collect(Collectors.toMap(Map.Entry::getKey, entry -> {
            MoltenIronBatchCalculationResultVo.EffectiveTarget target =
                new MoltenIronBatchCalculationResultVo.EffectiveTarget();
            target.setLower(entry.getValue().getEffectiveLower());
            target.setUpper(entry.getValue().getEffectiveUpper());
            return target;
        })));
    output.setCalcReportId(reportId);
    return output;
}

/**
 * 熔炼阶段不携带炉外原料和产品目标，避免联合求解把辅助加料混入炉内配料结果。
 */
private CastingChargeRecipeManageAutoCalcVo calcMeltingStage(CastingChargeRecipeManageSaveDto dto, Long currentDeptId) {
    requireStageBaseData(dto);
    List<CastingChargeRecipeDataBo.BatchingCharge> charges = dto.getBatchingResult().getCharges().stream()
        .filter(charge -> CoreUtils.isTrue(charge.getIsInsideCharge()))
        .collect(Collectors.toList());
    if (CollectionUtils.isEmpty(charges)) {
        throw new ServiceException("请先添加炉内主料配料明细");
    }

    Map<String, ChargeBatchingCalcByConstrainPyRequest.ElementBound> bounds = dto.getElementBounds().stream()
        .map(this::toMeltingBound)
        .filter(ChargeBatchingCalcByConstrainPyRequest.ElementBound::isValidBound)
        .collect(Collectors.toMap(ChargeBatchingCalcByConstrainPyRequest.ElementBound::getName, Function.identity()));
    if (MapUtils.isEmpty(bounds)) {
        throw new ServiceException("请填写炉内铁水成分控制的最低和最高目标");
    }

    AtomicInteger idx = new AtomicInteger();
    ChargeBatchingCalcByConstrainPyRequest request = new ChargeBatchingCalcByConstrainPyRequest();
    request.setParamId(String.format("[%s][%s][熔炼]", dto.getRecipeName(), dto.getRecipeNum()));
    request.setCalculationStage("MELTING");
    // 制定配方默认严格求解；用户显式开启后才允许 Python 给出可确认的松弛建议。
    request.setEnableSlackVariable(Boolean.TRUE.equals(dto.getEnableSlackVariable()));
    request.setStrategy(Optional.ofNullable(dto.getStrategy()).orElse(1));
    request.setLossModeFurnaceInside(Optional.ofNullable(dto.getLossModeFurnaceInside()).orElse(1));
    request.setLossModeFurnaceOutside(1);
    request.setElementBoundsMelting(bounds);
    request.setElementBoundsProduct(Collections.emptyMap());
    request.setMaterials(charges.stream()
        .map(charge -> toMeltingMaterial(charge, idx.getAndIncrement(), currentDeptId))
        .collect(Collectors.toList()));
    request.setTotalMeltingMass(dto.getTotalMeltingMass());
    request.setIsMainChargeOnly(true);

    ChargeBatchingCalcByConstrainPyResponse response = pyComputationService.chargeBatchingCalcByConstrain(request, currentDeptId);
    if (response == null || !CoreUtils.isTrue(response.getIsChargeInsideSolved())) {
        // 求解无解是正常业务结果：先固化 Python 的约束诊断，再把可读原因返回给页面。
        String calcMsg = buildStageFailureMessage("熔炼配料", response == null ? null : response.getChargeInsideDiagnostics());
        CastingChargeRecipeManageAutoCalcVo vo = new CastingChargeRecipeManageAutoCalcVo();
        vo.setRecipe(dto);
        vo.setSolved(false);
        vo.setCalcMsg(calcMsg);
        vo.setCalcReportId(saveCalcReport(dto, request, response, calcMsg, currentDeptId));
        return vo;
    }
    Map<Long, CastingChargeRecipeDataBo.BatchingCharge> chargeMap = charges.stream()
        .collect(Collectors.toMap(CastingChargeRecipeDataBo.BatchingCharge::getMaterialId, Function.identity()));
    Optional.ofNullable(response.getCharges()).orElse(Collections.emptyList()).forEach(result -> {
        CastingChargeRecipeDataBo.BatchingCharge charge = chargeMap.get(result.getMaterialId());
        if (charge != null) {
            charge.setMeltingMass(result.getMeltingMass());
        }
    });

    CastingChargeRecipeManageAutoCalcVo vo = new CastingChargeRecipeManageAutoCalcVo();
    vo.setRecipe(dto);
    vo.setSolved(true);
    vo.setElements(response.getElements());
    vo.setMeltingElementContents(Optional.ofNullable(response.getElements()).orElse(Collections.emptyMap()).entrySet().stream()
        .filter(entry -> entry.getValue().getMeltingContent() != null)
        .collect(Collectors.toMap(Map.Entry::getKey, entry -> entry.getValue().getMeltingContent())));
    vo.setIsSlacked(CoreUtils.isTrue(response.getIsSlacked()));
    vo.setSlackTargets(toConstraintSlackTargets(response.getChargeInsideSlackDetails(), bounds));
    vo.setCalcMsg(CoreUtils.isTrue(response.getIsSlacked()) ? "熔炼配料计算成功，已使用元素松弛" : "熔炼配料计算成功");
    // 分阶段试算同样需要进入历史，避免用户只能追溯旧的整配方试算。
    vo.setCalcReportId(saveCalcReport(dto, request, response, vo.getCalcMsg(), currentDeptId));
    return vo;
}

/**
 * Python 已按约束生成业务诊断，Java 仅补充阶段名称，避免再次解析求解器公式。
 */
private String buildStageFailureMessage(String stage, List<String> diagnostics) {
    if (CollectionUtils.isEmpty(diagnostics)) {
        return stage + "没有可行解，请检查原料、目标成分和用量限制";
    }
    return stage + "没有可行解：" + String.join("；", diagnostics);
}

/**
 * 炉后/浇注阶段仅使用炉外辅料，并且必须以本次熔炼得到的实际成分作为当前铁水。
 */
private CastingChargeRecipeManageAutoCalcVo calcOutsideStage(CastingChargeRecipeManageSaveDto dto, Long currentDeptId) {
    requireStageBaseData(dto);
    if (MapUtils.isEmpty(dto.getMeltingElementContents())) {
        throw new ServiceException("请先完成熔炼配料试算");
    }
    if (dto.getMaxOutsideAdditionMass() == null
        || NumberUtil.isLessOrEqual(dto.getMaxOutsideAdditionMass(), BigDecimal.ZERO)) {
        throw new ServiceException("炉后/浇注最大补加总量必须大于0");
    }
    List<CastingChargeRecipeDataBo.BatchingCharge> insideCharges = dto.getBatchingResult().getCharges().stream()
        .filter(charge -> CoreUtils.isTrue(charge.getIsInsideCharge()))
        .collect(Collectors.toList());
    BigDecimal currentMass = insideCharges.stream().map(CastingChargeRecipeDataBo.BatchingCharge::getMeltingMass)
        .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add);
    if (NumberUtil.isLessOrEqual(currentMass, BigDecimal.ZERO)) {
        throw new ServiceException("请先完成熔炼配料试算");
    }
    List<CastingChargeRecipeDataBo.BatchingCharge> outsideCharges = dto.getBatchingResult().getCharges().stream()
        .filter(charge -> CoreUtils.isTrue(charge.getIsOutsideCharge()))
        .collect(Collectors.toList());
    if (CollectionUtils.isEmpty(outsideCharges)) {
        throw new ServiceException("请先添加炉后/浇注辅料明细");
    }

    Map<String, ChargeBatchingAdjustPyRequest.ElementBound> bounds = dto.getElementBounds().stream()
        .map(bound -> toProductBound(bound, dto.getMeltingElementContents()))
        .filter(bound -> bound.getLower() != null && bound.getUpper() != null)
        .collect(Collectors.toMap(ChargeBatchingAdjustPyRequest.ElementBound::getName, Function.identity()));
    if (MapUtils.isEmpty(bounds)) {
        throw new ServiceException("请填写产品元素成分控制的最低和最高目标");
    }

    AtomicInteger idx = new AtomicInteger();
    ChargeBatchingAdjustPyRequest request = new ChargeBatchingAdjustPyRequest();
    request.setEnableSlack(Boolean.TRUE.equals(dto.getEnableSlackVariable()));
    request.setRequestId(UUID.randomUUID().toString());
    request.setStrategy(1);
    request.setLossModeFurnaceInside(Optional.ofNullable(dto.getLossModeFurnaceOutside()).orElse(1));
    request.setElementBoundsMelting(bounds);
    request.setMaterials(outsideCharges.stream()
        .map(charge -> toOutsideMaterial(charge, idx.getAndIncrement(), currentDeptId))
        .collect(Collectors.toList()));
    request.setCurrentMass(currentMass);
    // 配方设计没有具体炉体，显式补加上限为 Python 提供可执行的容量边界。
    request.setMaxTotalChargeMass(dto.getMaxOutsideAdditionMass());
    request.setEnableMaxTotalChargeMass(true);
    request.setMaxTotalChargeMassFrom("ERP配方试算");

    ChargeBatchingAdjustPyResponse response = pyComputationService.chargeBatchingAdjust(request, currentDeptId);
    if (response == null || !CoreUtils.isTrue(response.getIsChargeInsideSolved())) {
        // 炉后求解失败同样保留本次 Python 诊断，未保存配方可通过报告 ID 立即查看。
        String calcMsg = buildOutsideStageFailureMessage(response);
        CastingChargeRecipeManageAutoCalcVo vo = new CastingChargeRecipeManageAutoCalcVo();
        vo.setRecipe(dto);
        vo.setSolved(false);
        vo.setCalcMsg(calcMsg);
        vo.setCalcReportId(saveOutsideStageCalcReport(dto, request, response, calcMsg, currentDeptId));
        return vo;
    }
    Map<Long, CastingChargeRecipeDataBo.BatchingCharge> chargeMap = outsideCharges.stream()
        .collect(Collectors.toMap(CastingChargeRecipeDataBo.BatchingCharge::getMaterialId, Function.identity()));
    Optional.ofNullable(response.getCharges()).orElse(Collections.emptyList()).forEach(result -> {
        CastingChargeRecipeDataBo.BatchingCharge charge = chargeMap.get(result.getMaterialId());
        if (charge == null) {
            return;
        }
        if (charge.getTappingProportion() != null) {
            charge.setTappingMass(result.getMeltingMass());
            charge.setPouringMass(null);
        } else {
            charge.setPouringMass(result.getMeltingMass());
            charge.setTappingMass(null);
        }
    });

    CastingChargeRecipeManageAutoCalcVo vo = new CastingChargeRecipeManageAutoCalcVo();
    vo.setRecipe(dto);
    vo.setSolved(true);
    vo.setIsSlacked(CoreUtils.isTrue(response.getIsSlacked()));
    vo.setSlackTargets(toAdjustSlackTargets(response.getElementBoundsMelting(), bounds));
    vo.setCalcMsg(CoreUtils.isTrue(response.getIsSlacked()) ? "炉后/浇注配料计算成功，已使用元素松弛" : "炉后/浇注配料计算成功");
    vo.setCalcReportId(saveOutsideStageCalcReport(dto, request, response, vo.getCalcMsg(), currentDeptId));
    return vo;
}

/**
 * 阶段试算共享配方主体校验；原料和目标的阶段边界由各自方法继续校验。
 */
private void requireStageBaseData(CastingChargeRecipeManageSaveDto dto) {
    if (dto.getTotalMeltingMass() == null || NumberUtil.isLessOrEqual(dto.getTotalMeltingMass(), BigDecimal.ZERO)) {
        throw new ServiceException("炉内目标总重必须大于0");
    }
    if (CollectionUtils.isEmpty(dto.getElementBounds())) {
        throw new ServiceException("请至少添加一个元素成分控制");
    }
    if (dto.getBatchingResult() == null || CollectionUtils.isEmpty(dto.getBatchingResult().getCharges())) {
        throw new ServiceException("请先添加配料明细");
    }
}

private ChargeBatchingCalcByConstrainPyRequest.ElementBound toMeltingBound(CastingChargeRecipeDataBo.ElementBound source) {
    ChargeBatchingCalcByConstrainPyRequest.ElementBound target = new ChargeBatchingCalcByConstrainPyRequest.ElementBound();
    target.setName(source.getName());
    target.setLower(source.getMeltingLower());
    target.setUpper(source.getMeltingUpper());
    target.setControl(source.getMeltingControl());
    target.setLoss(dividedBy100(source.getInsideLoss(), DEFAULT_LOSS));
    return target;
    return target;
}

private ChargeBatchingAdjustPyRequest.ElementBound toProductBound(
    CastingChargeRecipeDataBo.ElementBound source, Map<String, BigDecimal> meltingElementContents
) {
    ChargeBatchingAdjustPyRequest.ElementBound target = new ChargeBatchingAdjustPyRequest.ElementBound();
    target.setName(source.getName());
    target.setCurrent(meltingElementContents.get(source.getName()));
    target.setLower(source.getProductLower());
    target.setUpper(source.getProductUpper());
    target.setControl(source.getProductControl());
    target.setLoss(dividedBy100(source.getOutsideLoss(), DEFAULT_LOSS));
    return target;
}

private ChargeBatchingCalcByConstrainPyRequest.Material toMeltingMaterial(
    CastingChargeRecipeDataBo.BatchingCharge source, int idx, Long currentDeptId
) {
    ChargeBatchingCalcByConstrainPyRequest.Material target = new ChargeBatchingCalcByConstrainPyRequest.Material();
    target.setMaterialId(source.getMaterialId());
    target.setIdx(idx);
    target.setName(source.getMaterialName());
    target.setPrice(CoreUtils.nullToZero(source.getMaterialPrice()));
    target.setIsMainCharge(true);
    target.setIsFurnaceInsideCharge(true);
    target.setInsideProportionLower(source.getMeltingProportionLower());
    target.setInsideProportionUpper(source.getMeltingProportionUpper());
    target.setInsideProportionFixed(source.getMeltingProportionFixed());
    target.setIsFurnaceOutsideCharge(false);
    target.setChargeAccuracy(Optional.ofNullable(getMaterialInfoById(source.getMaterialId(), currentDeptId))
        .map(TbMaterialInfo::getFeedingAccuracy).orElse(BigDecimal.ONE));
    target.setElements(toConstraintMaterialElements(source, currentDeptId));
    return target;
}

private ChargeBatchingAdjustPyRequest.Material toOutsideMaterial(
    CastingChargeRecipeDataBo.BatchingCharge source, int idx, Long currentDeptId
) {
    ChargeBatchingAdjustPyRequest.Material target = new ChargeBatchingAdjustPyRequest.Material();
    target.setMaterialId(source.getMaterialId());
    target.setIdx(idx);
    target.setName(source.getMaterialName());
    target.setPrice(CoreUtils.nullToZero(source.getMaterialPrice()));
    target.setChargeAccuracy(Optional.ofNullable(getMaterialInfoById(source.getMaterialId(), currentDeptId))
        .map(TbMaterialInfo::getFeedingAccuracy).orElse(BigDecimal.ONE));
    target.setElements(toAdjustMaterialElements(source, currentDeptId));
    return target;
}

private Map<String, ChargeBatchingCalcByConstrainPyRequest.MaterialElement> toConstraintMaterialElements(
    CastingChargeRecipeDataBo.BatchingCharge source, Long currentDeptId
) {
    Map<String, ChargeBatchingCalcByConstrainPyRequest.MaterialElement> result = new HashMap<>();
    Map<String, CastingMaterialElementBo> recoveryMap = Optional.ofNullable(source.getMaterialElements()).orElse(Collections.emptyMap());
    getMaterialElementConentMap(source.getMaterialId(), currentDeptId).forEach((name, element) -> {
        ChargeBatchingCalcByConstrainPyRequest.MaterialElement target = new ChargeBatchingCalcByConstrainPyRequest.MaterialElement();
        target.setLower(element.getContentMin());
        target.setUpper(element.getContentMax());
        target.setFixed(element.getContentFixed());
        // 配方显式调整值优先；没有配方级覆盖时沿用物料主数据，二者都未配置才交给 Python 按 100% 兼容。
        target.setRecovery(Optional.ofNullable(recoveryMap.get(name))
            .map(CastingMaterialElementBo::getAdjustRecovery).orElse(element.getBurningRate()));
        result.put(name, target);
    });
    return result;
}

private Map<String, ChargeBatchingAdjustPyRequest.MaterialElement> toAdjustMaterialElements(
    CastingChargeRecipeDataBo.BatchingCharge source, Long currentDeptId
) {
    Map<String, ChargeBatchingAdjustPyRequest.MaterialElement> result = new HashMap<>();
    Map<String, CastingMaterialElementBo> recoveryMap = Optional.ofNullable(source.getMaterialElements()).orElse(Collections.emptyMap());
    getMaterialElementConentMap(source.getMaterialId(), currentDeptId).forEach((name, element) -> {
        ChargeBatchingAdjustPyRequest.MaterialElement target = new ChargeBatchingAdjustPyRequest.MaterialElement();
        target.setName(name);
        target.setLower(element.getContentMin());
        target.setUpper(element.getContentMax());
        target.setFixed(element.getContentFixed());
        Optional.ofNullable(recoveryMap.get(name)).map(CastingMaterialElementBo::getAdjustRecovery).ifPresent(target::setRecovery);
        result.put(name, target);
    });
    return result;
}

private Map<String, CastingChargeRecipeManageAutoCalcVo.SlackTarget> toConstraintSlackTargets(
    Map<String, ChargeBatchingCalcByConstrainPyResponse.SlackDetail> details,
    Map<String, ChargeBatchingCalcByConstrainPyRequest.ElementBound> originalBounds
) {
    return Optional.ofNullable(details).orElse(Collections.emptyMap()).entrySet().stream()
        .map(entry -> Map.entry(entry.getKey(), createSlackTarget(
            changedSlackValue(entry.getValue().getEffectiveLower(), Optional.ofNullable(originalBounds.get(entry.getKey())).map(ChargeBatchingCalcByConstrainPyRequest.ElementBound::getLower).orElse(null)),
            changedSlackValue(entry.getValue().getEffectiveUpper(), Optional.ofNullable(originalBounds.get(entry.getKey())).map(ChargeBatchingCalcByConstrainPyRequest.ElementBound::getUpper).orElse(null))
        )))
        .filter(entry -> entry.getValue().getLower() != null || entry.getValue().getUpper() != null)
        .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
}

private Map<String, CastingChargeRecipeManageAutoCalcVo.SlackTarget> toAdjustSlackTargets(
    Map<String, ChargeBatchingAdjustPyRequest.ElementBound> details,
    Map<String, ChargeBatchingAdjustPyRequest.ElementBound> originalBounds
) {
    return Optional.ofNullable(details).orElse(Collections.emptyMap()).entrySet().stream()
        .map(entry -> Map.entry(entry.getKey(), createSlackTarget(
            changedSlackValue(entry.getValue().getSlackLowerPct(), Optional.ofNullable(originalBounds.get(entry.getKey())).map(ChargeBatchingAdjustPyRequest.ElementBound::getLower).orElse(null)),
            changedSlackValue(entry.getValue().getSlackUpperPct(), Optional.ofNullable(originalBounds.get(entry.getKey())).map(ChargeBatchingAdjustPyRequest.ElementBound::getUpper).orElse(null))
        )))
        .filter(entry -> entry.getValue().getLower() != null || entry.getValue().getUpper() != null)
        .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
}

/**
 * 求解器会完整返回有效上下限；页面只应提示被放宽的一侧，原值相同的一侧无需再次确认。
 */
private BigDecimal changedSlackValue(BigDecimal effectiveValue, BigDecimal originalValue) {
    return effectiveValue != null && (originalValue == null || effectiveValue.compareTo(originalValue) != 0) ? effectiveValue : null;
}

private CastingChargeRecipeManageAutoCalcVo.SlackTarget createSlackTarget(BigDecimal lower, BigDecimal upper) {
    CastingChargeRecipeManageAutoCalcVo.SlackTarget target = new CastingChargeRecipeManageAutoCalcVo.SlackTarget();
    target.setLower(lower);
    target.setUpper(upper);
    return target;
}

/**
 * 按当前工厂和配方查询试算历史，报告内容只由计算发生时的快照决定。
 */
public IPage<CastingChargeRecipeCalcReportVo> calcReportPage(Long recipeId, Long reportId, String keyword, PageQuery pageQuery) {
    Long currentDeptId = atsiTenantService.getCurrentDeptId();
    // 历史查询未显式传入分页大小时仍按列表接口分页，避免其他调用端误触发全量报告查询。
    if (pageQuery.getPageSize() == null) {
        pageQuery.setPageSize(20);
    }
    // 详情页传 recipeId 查询单配方历史；未保存试算传 reportId 精确读取本次报告。
    var queryWrapper = Wrappers.<TbCastingChargeRecipeCalcReport>lambdaQuery()
        .eq(TbCastingChargeRecipeCalcReport::getTenantId, currentDeptId);
    if (recipeId != null) {
        queryWrapper.eq(TbCastingChargeRecipeCalcReport::getRecipeId, recipeId);
    }
    if (reportId != null) {
        queryWrapper.eq(TbCastingChargeRecipeCalcReport::getId, reportId);
    }
    // 历史菜单使用一个搜索框同时匹配配方编码和名称，始终保持当前工厂的数据边界。
    if (StringUtils.isNotBlank(keyword)) {
        queryWrapper.and(wrapper -> wrapper
            .like(TbCastingChargeRecipeCalcReport::getRecipeNum, keyword)
            .or()
            .like(TbCastingChargeRecipeCalcReport::getRecipeName, keyword));
    }
    IPage<TbCastingChargeRecipeCalcReport> reportPage = tbCastingChargeRecipeCalcReportMapper.selectPage(
        pageQuery.build(),
        queryWrapper.orderByDesc(TbCastingChargeRecipeCalcReport::getCreateTime)
    );
    return toCalcReportPage(reportPage);
}

/** 铁水批次历史只按服务端确认的工厂和 allocation 查询，避免配方维度混入其他炉次。 */
public IPage<CastingChargeRecipeCalcReportVo> calcReportPageByAllocation(
    Long tenantId, Long allocationId, PageQuery pageQuery) {
    IPage<TbCastingChargeRecipeCalcReport> reportPage = tbCastingChargeRecipeCalcReportMapper.selectPage(
        pageQuery.build(),
        Wrappers.<TbCastingChargeRecipeCalcReport>lambdaQuery()
            .eq(TbCastingChargeRecipeCalcReport::getTenantId, tenantId)
            .eq(TbCastingChargeRecipeCalcReport::getMoltenIronAllocationId, allocationId)
            .orderByDesc(TbCastingChargeRecipeCalcReport::getCreateTime)
    );
    return toCalcReportPage(reportPage);
}

private IPage<CastingChargeRecipeCalcReportVo> toCalcReportPage(
    IPage<TbCastingChargeRecipeCalcReport> reportPage) {
    return PageUtils.toPage(reportPage, report -> {
        CastingChargeRecipeCalcReportVo vo = new CastingChargeRecipeCalcReportVo();
        vo.setId(report.getId());
        vo.setRecipeId(report.getRecipeId());
        vo.setRecipeNum(report.getRecipeNum());
        vo.setRecipeName(report.getRecipeName());
        vo.setCalcMsg(report.getCalcMsg());
        vo.setIsChargeInsideSolved(report.getIsChargeInsideSolved());
        vo.setIsChargeOutsideSolved(report.getIsChargeOutsideSolved());
        vo.setMarkdownReport(report.getMarkdownReport());
        vo.setCreateTime(report.getCreateTime());
        return vo;
    });
}

