public void shouldCalculateManualRecipeWithElementTargetsAndMaterialElements() {
    TbMoltenIronBatchAllocation allocation = editableAllocation();
    allocation.setFurnaceId("FURNACE-001");
    allocation.setAllocatedWeight(BigDecimal.valueOf(1000));
    allocation.setRemainingMoltenIronWeight(BigDecimal.valueOf(200));
    when(atsiTenantService.getCurrentDeptId()).thenReturn(100L);
    when(allocationMapper.selectOne(any())).thenReturn(allocation);
    TbMoltenIronBatch batch = batch(5001L);
    batch.setRecipeId(7001L);
    when(planService.requireBatch(3001L, 100L)).thenReturn(batch);
    com.allthinkstars.framework.iot.erp.datasource.entities.TbCastingChargeRecipe recipe =
        new com.allthinkstars.framework.iot.erp.datasource.entities.TbCastingChargeRecipe();
    recipe.setTenantId(100L);
    recipe.setRecipeType(2);
    when(recipeMapper.selectById(7001L)).thenReturn(recipe);
    CastingChargeRecipeManageGetVo manualRecipe = recipeData();
    manualRecipe.setRecipeType(2);
    manualRecipe.setRecipeName("测试手动配方");
    CastingMaterialElementBo recipeCarbon = new CastingMaterialElementBo();
    recipeCarbon.setName("C");
    recipeCarbon.setAdjustRecovery(BigDecimal.valueOf(88));
    CastingChargeRecipeManageGetVo.BatchingChargeVo recipeCharge =
        new CastingChargeRecipeManageGetVo.BatchingChargeVo();
    recipeCharge.setMaterialId(8001L);
    recipeCharge.setMaterialElements(Map.of("C", recipeCarbon));
    manualRecipe.getBatchingResult().setCharges(Collections.singletonList(recipeCharge));
    when(recipeService.get(7001L, 100L)).thenReturn(manualRecipe);

    MaterialPoolMaterialElementVo material = new MaterialPoolMaterialElementVo();
    material.setMaterialId(8001L);
    material.setMaterialName("低价炉料");
    material.setMaterialAlias("低价别名");
    material.setLatestUnitPrice(BigDecimal.ONE);
    MaterialPoolElementVo materialCarbon = new MaterialPoolElementVo();
    materialCarbon.setElementName("C");
    materialCarbon.setContentFixed(BigDecimal.valueOf(3.1));
    material.setElements(Collections.singletonList(materialCarbon));
    when(materialPoolManageService.getCalculationMaterials(Collections.singletonList(8001L), 100L))
        .thenReturn(Collections.singletonList(material));
    MoltenIronBatchCalculationResultVo calculated = new MoltenIronBatchCalculationResultVo();
    Map<String, BigDecimal> residualElements = Map.of(
        "Mn", BigDecimal.valueOf(0.6), "Cr", BigDecimal.valueOf(0.2));
    when(recipeService.calcMoltenIronBatch(any(), eq("FURNACE-001"), eq(BigDecimal.valueOf(200)),
        eq(residualElements), eq(100L), eq(1001L))).thenReturn(calculated);
    when(allocationMapper.updateCalculation(eq(1001L), eq(100L), any(), any(), any(), any()))
        .thenReturn(1);
    when(allocationMapper.selectById(1001L)).thenReturn(allocation);

    MoltenIronBatchCalculationInput input = new MoltenIronBatchCalculationInput();
    MoltenIronBatchCalculationInput.Material selected = new MoltenIronBatchCalculationInput.Material();
    selected.setMaterialId(8001L);
    input.setMaterials(Collections.singletonList(selected));
    MoltenIronBatchCalculationInput.ElementTarget carbonTarget =
        new MoltenIronBatchCalculationInput.ElementTarget();
    carbonTarget.setName("C");
    carbonTarget.setMeltingLower(BigDecimal.valueOf(2.9));
    // constrained=null 模拟旧客户端；缺省值必须继续按启用约束处理。
    carbonTarget.setConstrained(null);
    MoltenIronBatchCalculationInput.ElementTarget siliconTarget =
        new MoltenIronBatchCalculationInput.ElementTarget();
    siliconTarget.setName("Si");
    siliconTarget.setConstrained(false);
    MoltenIronBatchCalculationInput.ElementTarget extraManganeseTarget =
        new MoltenIronBatchCalculationInput.ElementTarget();
    extraManganeseTarget.setName("Mn");
    extraManganeseTarget.setMeltingControl(BigDecimal.valueOf(0.7));
    input.setElementTargets(List.of(carbonTarget, siliconTarget, extraManganeseTarget));
    input.setResidualElements(residualElements);
    MoltenIronBatchCalculationInput.ResidualElementSource source =
        new MoltenIronBatchCalculationInput.ResidualElementSource();
    source.setType("AUTO_SPECTRUM");
    source.setPreviousBatchId(6001L);
    source.setJournalId(7001L);
    source.setDetectedAt(LocalDateTime.of(2026, 8, 21, 15, 2));
    input.setResidualElementSource(source);
    service.calculate(1001L, input);

    ArgumentCaptor<CastingChargeRecipeManageSaveDto> request =
        ArgumentCaptor.forClass(CastingChargeRecipeManageSaveDto.class);
    verify(recipeService).calcMoltenIronBatch(request.capture(), eq("FURNACE-001"),
        eq(BigDecimal.valueOf(200)), eq(input.getResidualElements()), eq(100L), eq(1001L));
    // null 兼容旧客户端并保留 C，显式关闭的 Si 被移出求解目标，配方外 Mn 不扩大目标集合。
    assertEquals(1, request.getValue().getElementBounds().size());
    assertEquals("C", request.getValue().getElementBounds().get(0).getName());
    assertEquals(BigDecimal.valueOf(2.9),
        request.getValue().getElementBounds().get(0).getMeltingLower());
    assertEquals(residualElements, input.getResidualElements());
    assertFalse(input.getResidualElements().containsKey("Si"));
    assertEquals(8001L, request.getValue().getBatchingResult().getCharges().get(0).getMaterialId().longValue());
    assertEquals("低价别名", request.getValue().getBatchingResult().getCharges().get(0).getMaterialAlias());
    assertEquals(BigDecimal.valueOf(88), request.getValue().getBatchingResult().getCharges().get(0)
        .getMaterialElements().get("C").getAdjustRecovery());
    assertEquals(null,
        request.getValue().getBatchingResult().getCharges().get(0).getMeltingProportionUpper());
    assertEquals(BigDecimal.valueOf(1000), request.getValue().getTotalMeltingMass());
    verify(materialPoolManageService).getCalculationMaterials(Collections.singletonList(8001L), 100L);

    // 来源元数据随 calculationInput 原样保存，刷新页面和历史报告不需要重新猜测光谱。
    ArgumentCaptor<String> savedInput = ArgumentCaptor.forClass(String.class);
    verify(allocationMapper).updateCalculation(eq(1001L), eq(100L), savedInput.capture(),
        any(), any(), any());
    MoltenIronBatchCalculationInput persisted = SerializationUtils.fromStr(
        savedInput.getValue(), MoltenIronBatchCalculationInput.class);
    assertEquals("AUTO_SPECTRUM", persisted.getResidualElementSource().getType());
    assertEquals(Long.valueOf(6001L), persisted.getResidualElementSource().getPreviousBatchId());
    assertEquals(Long.valueOf(7001L), persisted.getResidualElementSource().getJournalId());
    assertEquals(Boolean.FALSE, persisted.getElementTargets().get(1).getConstrained());
}

