package com.allthinkstars.framework.datasource.tenant;

import lombok.extern.slf4j.Slf4j;
import org.apache.ibatis.executor.Executor;
import org.apache.ibatis.mapping.MappedStatement;
import org.apache.ibatis.mapping.ResultMap;
import org.apache.ibatis.plugin.Interceptor;
import org.apache.ibatis.plugin.Intercepts;
import org.apache.ibatis.plugin.Invocation;
import org.apache.ibatis.plugin.Plugin;
import org.apache.ibatis.plugin.Signature;
import org.apache.ibatis.session.ResultHandler;
import org.apache.ibatis.session.RowBounds;
import org.apache.ibatis.session.SqlSessionFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.SmartInitializingSingleton;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.core.annotation.AnnotatedElementUtils;
import org.springframework.stereotype.Component;

import java.lang.reflect.Method;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * 根据 Mapper/结果实体上的 {@link TenantStorage} 标记建立租户数据库路由上下文。
 * 默认不建立路由，因此未标记的数据访问始终使用云端数据库。
 */
@Slf4j
@Component
// 必须包在分页拦截器（PageHelper/MybatisPlus）外层，确保它们生成的 count 查询也处于租户路由上下文中。
// Spring 会按 @Order 排序 Interceptor[]；MyBatis 按注册顺序逐层包装，最低优先级会最后注册、最外层执行。
@Order(Ordered.LOWEST_PRECEDENCE)
@Intercepts({
    @Signature(type = Executor.class, method = "query", args = {
        MappedStatement.class, Object.class, RowBounds.class, ResultHandler.class
    }),
    @Signature(type = Executor.class, method = "query", args = {
        MappedStatement.class, Object.class, RowBounds.class, ResultHandler.class,
        org.apache.ibatis.cache.CacheKey.class, org.apache.ibatis.mapping.BoundSql.class
    }),
    @Signature(type = Executor.class, method = "update", args = {
        MappedStatement.class, Object.class
    })
})
public class TenantStorageMybatisInterceptor implements Interceptor, SmartInitializingSingleton {

    private final Map<String, RouteMode> statementRouteCache = new ConcurrentHashMap<>();

    @Autowired(required = false)
    private ObjectProvider<SqlSessionFactory> sqlSessionFactoryProvider;

    /**
     * PageHelper 通过自身的 @PostConstruct 在 SqlSessionFactory 创建后追加 PageInterceptor，
     * 仅依赖 @Order 无法保证本拦截器仍位于最外层。所有单例初始化完成后重新将本拦截器放到末尾，
     * 这样 PageHelper 生成的 *_COUNT 查询进入 MybatisPlus 租户拦截器前，路由上下文一定已建立。
     */
    @Override
    public void afterSingletonsInstantiated() {
        if (sqlSessionFactoryProvider == null) {
            return;
        }
        sqlSessionFactoryProvider.stream().forEach(sqlSessionFactory -> {
            java.util.List<Interceptor> interceptors = sqlSessionFactory.getConfiguration().getInterceptors();
            // getInterceptors() 返回不可变视图，只能读取，不能 remove/add。
            // 如果 PageHelper 已经追加到本拦截器之后，则再追加同一个实例，使其成为最外层；
            // 若本来已经在末尾，则无需重复注册。
            if (interceptors.isEmpty() || interceptors.get(interceptors.size() - 1) != this) {
                sqlSessionFactory.getConfiguration().addInterceptor(this);
            }
        });
    }

    @Override
    public Object intercept(Invocation invocation) throws Throwable {
        MappedStatement mappedStatement = (MappedStatement) invocation.getArgs()[0];
        RouteMode routeMode = resolveRouteMode(mappedStatement);
        if (routeMode == RouteMode.DEFAULT || TenantRouteContext.isRouteForced()) {
            return invocation.proceed();
        }
        try (TenantRouteContext.Scope ignored = routeMode == RouteMode.TENANT
            ? TenantRouteContext.useTenantRoute() : TenantRouteContext.useCloudRoute()) {
            return invocation.proceed();
        }
    }

    @Override
    public Object plugin(Object target) {
        return Plugin.wrap(target, this);
    }

    private RouteMode resolveRouteMode(MappedStatement mappedStatement) {
        return statementRouteCache.computeIfAbsent(mappedStatement.getId(), key -> {
            int separator = key.lastIndexOf('.');
            if (separator <= 0 || separator == key.length() - 1) {
                return RouteMode.DEFAULT;
            }
            String mapperName = key.substring(0, separator);
            String methodName = key.substring(separator + 1);
            try {
                Class<?> mapperType = Class.forName(mapperName);
                for (Method method : mapperType.getMethods()) {
                    if (method.getName().equals(methodName)) {
                        TenantStorage annotation = AnnotatedElementUtils.findMergedAnnotation(
                            method, TenantStorage.class);
                        if (annotation != null) {
                            return annotation.value() ? RouteMode.TENANT : RouteMode.CLOUD;
                        }
                    }
                }
                TenantStorage typeAnnotation = AnnotatedElementUtils.findMergedAnnotation(
                    mapperType, TenantStorage.class);
                if (typeAnnotation != null) {
                    return typeAnnotation.value() ? RouteMode.TENANT : RouteMode.CLOUD;
                }
                for (ResultMap resultMap : mappedStatement.getResultMaps()) {
                    TenantStorage entityAnnotation = AnnotatedElementUtils.findMergedAnnotation(
                        resultMap.getType(), TenantStorage.class);
                    if (entityAnnotation != null) {
                        return entityAnnotation.value() ? RouteMode.TENANT : RouteMode.CLOUD;
                    }
                }
            } catch (ClassNotFoundException e) {
                log.debug("无法解析 Mapper 类型，按云端数据源处理: {}", mapperName);
            }
            return RouteMode.DEFAULT;
        });
    }

    private enum RouteMode {
        DEFAULT,
        CLOUD,
        TENANT
    }
}
package com.allthinkstars.framework.datasource.tenant;

import com.baomidou.dynamic.datasource.toolkit.DynamicDataSourceContextHolder;
import org.springframework.jdbc.datasource.AbstractDataSource;

import javax.sql.DataSource;
import java.io.Closeable;
import java.io.IOException;
import java.sql.Connection;
import java.sql.SQLException;
import java.util.Collections;
import java.util.Map;

/**
 * 动态数据源中的租户感知包装器。
 *
 * <p>默认使用云端数据源；只有 {@link TenantStorage} 标记建立租户路由上下文时，
 * 才按租户切换到客户数据库。逻辑数据源只决定数据库名称，不参与云端或客户侧的选择。</p>
 */
public class TenantAwareDataSource extends AbstractDataSource implements Closeable {

    private final String logicalName;
    private final DataSource cloudDataSource;
    private final Map<String, DataSource> cloudDataSources;
    private final TenantDataSourceRegistry registry;
    private final TenantIdResolver tenantIdResolver;

    public TenantAwareDataSource(String logicalName,
                                 DataSource cloudDataSource,
                                 TenantDataSourceRegistry registry,
                                 TenantIdResolver tenantIdResolver) {
        this(logicalName, cloudDataSource, Collections.singletonMap(logicalName, cloudDataSource),
            registry, tenantIdResolver);
    }

    public TenantAwareDataSource(String logicalName,
                                 DataSource cloudDataSource,
                                 Map<String, DataSource> cloudDataSources,
                                 TenantDataSourceRegistry registry,
                                 TenantIdResolver tenantIdResolver) {
        this.logicalName = logicalName;
        this.cloudDataSource = cloudDataSource;
        this.cloudDataSources = cloudDataSources;
        this.registry = registry;
        this.tenantIdResolver = tenantIdResolver;
    }

    public DataSource getCloudDataSource() {
        return cloudDataSource;
    }

    @Override
    public Connection getConnection() throws SQLException {
        return targetDataSource().getConnection();
    }

    @Override
    public Connection getConnection(String username, String password) throws SQLException {
        return targetDataSource().getConnection(username, password);
    }

    @Override
    public boolean isWrapperFor(Class<?> iface) throws SQLException {
        return iface.isInstance(this) || cloudDataSource.isWrapperFor(iface);
    }

    @Override
    public <T> T unwrap(Class<T> iface) throws SQLException {
        if (iface.isInstance(this)) {
            return iface.cast(this);
        }
        return cloudDataSource.unwrap(iface);
    }

    @Override
    public void close() throws IOException {
        if (cloudDataSource instanceof Closeable) {
            ((Closeable) cloudDataSource).close();
        }
    }

    private DataSource targetDataSource() {
        // 默认访问云端；仅标记了 @TenantStorage 的调用才允许切换客户数据库。
        if (!TenantRouteContext.isTenantRouteRequested()) {
            return cloudDataSource;
        }

        String currentLogicalName = DynamicDataSourceContextHolder.peek();
        String targetLogicalName = currentLogicalName == null || currentLogicalName.trim().isEmpty()
            ? logicalName : currentLogicalName;
        DataSource targetCloudDataSource = cloudDataSources.getOrDefault(targetLogicalName, cloudDataSource);

        Long tenantId = TenantContext.getTenantId();
        if (tenantId == null) {
            tenantId = tenantIdResolver.resolveTenantId();
        }
        if (tenantId == null) {
            // 没有租户上下文时保留云端回退能力，兼容启动初始化、平台管理和定时任务。
            return targetCloudDataSource;
        }
        // 事务可能已经持有默认叶子数据源，但 Mapper 上的 @DS 此时仍在上下文中。
        // 客户连接必须采用当前逻辑库名，不能被事务开始时选中的默认 logicalName 锁死。
        return registry.getDataSource(tenantId, targetLogicalName, targetCloudDataSource);
    }
}
package com.allthinkstars.framework.datasource.tenant;

import lombok.AccessLevel;
import lombok.NoArgsConstructor;

/** 当前线程是否明确要求访问租户数据库。 */
@NoArgsConstructor(access = AccessLevel.PRIVATE)
public final class TenantRouteContext {

    /** 普通路由选择，主要由 Mapper 上的 {@link TenantStorage} 控制。 */
    private static final ThreadLocal<Boolean> ROUTE = new ThreadLocal<>();
    /** 事务级路由选择，确保同一个本地事务内不会被 Mapper 注解再次切换连接。 */
    private static final ThreadLocal<Boolean> FORCED_ROUTE = new ThreadLocal<>();

    public static boolean isTenantRouteRequested() {
        Boolean forcedRoute = FORCED_ROUTE.get();
        return Boolean.TRUE.equals(forcedRoute != null ? forcedRoute : ROUTE.get());
    }

    public static boolean isRouteForced() {
        return FORCED_ROUTE.get() != null;
    }

    public static Scope useTenantRoute() {
        return useRoute(ROUTE, true);
    }

    /**
     * 临时关闭租户数据库路由。
     *
     * <p>用于在客户数据库事务中挂起当前事务后，显式开启独立的云端事务。
     * Scope 关闭时会恢复进入前的租户路由状态。</p>
     */
    public static Scope useCloudRoute() {
        return useRoute(ROUTE, false);
    }

    /** 强制整个独立事务访问客户数据库，事务内的 Mapper 注解不能覆盖该选择。 */
    public static Scope forceTenantRoute() {
        return useRoute(FORCED_ROUTE, true);
    }

    /** 强制整个独立事务访问云端数据库，事务内的 Mapper 注解不能覆盖该选择。 */
    public static Scope forceCloudRoute() {
        return useRoute(FORCED_ROUTE, false);
    }

    public static void clear() {
        ROUTE.remove();
        FORCED_ROUTE.remove();
    }

    private static Scope useRoute(ThreadLocal<Boolean> holder, boolean tenantRoute) {
        Boolean previous = holder.get();
        holder.set(tenantRoute);
        return new Scope(holder, previous);
    }

    public static final class Scope implements AutoCloseable {
        private final ThreadLocal<Boolean> holder;
        private final Boolean previous;
        private boolean closed;

        private Scope(ThreadLocal<Boolean> holder, Boolean previous) {
            this.holder = holder;
            this.previous = previous;
        }

        @Override
        public void close() {
            if (closed) {
                return;
            }
            closed = true;
            if (previous == null) {
                holder.remove();
            } else {
                holder.set(previous);
            }
        }
    }
}

