/** 当前线程是否明确要求访问租户数据库。 */
@NoArgsConstructor(access = AccessLevel.PRIVATE)
public final class TenantRouteContext {

    /** 普通路由选择，主要由 Mapper 上的 {@link TenantStorage} 控制。 */
    private static final ThreadLocal<Boolean> ROUTE = new ThreadLocal<>();
    /** 事务级路由选择，确保同一个本地事务内不会被 Mapper 注解再次切换连接。 */
    private static final ThreadLocal<Boolean> FORCED_ROUTE = new ThreadLocal<>();

    public static boolean isTenantRouteRequested() {
        Boolean forcedRoute = FORCED_ROUTE.get();
        return Boolean.TRUE.equals(forcedRoute != null ? forcedRoute : ROUTE.get());
    }

    public static boolean isRouteForced() {
        return FORCED_ROUTE.get() != null;
    }

    public static Scope useTenantRoute() {
        return useRoute(ROUTE, true);
    }

    /**
     * 临时关闭租户数据库路由。
     *
     * <p>用于在客户数据库事务中挂起当前事务后，显式开启独立的云端事务。
     * Scope 关闭时会恢复进入前的租户路由状态。</p>
     */
    public static Scope useCloudRoute() {
        return useRoute(ROUTE, false);
    }

    /** 强制整个独立事务访问客户数据库，事务内的 Mapper 注解不能覆盖该选择。 */
    public static Scope forceTenantRoute() {
        return useRoute(FORCED_ROUTE, true);
    }

    /** 强制整个独立事务访问云端数据库，事务内的 Mapper 注解不能覆盖该选择。 */
    public static Scope forceCloudRoute() {
        return useRoute(FORCED_ROUTE, false);
    }

    public static void clear() {
        ROUTE.remove();
        FORCED_ROUTE.remove();
    }

    private static Scope useRoute(ThreadLocal<Boolean> holder, boolean tenantRoute) {
        Boolean previous = holder.get();
        holder.set(tenantRoute);
        return new Scope(holder, previous);
    }

    public static final class Scope implements AutoCloseable {
        private final ThreadLocal<Boolean> holder;
        private final Boolean previous;
        private boolean closed;

        private Scope(ThreadLocal<Boolean> holder, Boolean previous) {
            this.holder = holder;
            this.previous = previous;
        }

        @Override
        public void close() {
            if (closed) {
                return;
            }
            closed = true;
            if (previous == null) {
                holder.remove();
            } else {
                holder.set(previous);
            }
        }
    }
}

