    private TbMaterialInfo getMaterialInfoById(Long materialId, Long currentDeptId) {
        TbMaterialInfo condition = new TbMaterialInfo();
        // 防御性编程
        condition.setId(Objects.requireNonNull(materialId));
        // 为什么可空？
        // 因为ERP服务的SQL有自动的租户ID注入
        condition.setTenantId(currentDeptId);
        return tbMaterialInfoMapper.selectOne(Wrappers.query(condition));
    }

    private String getMaterialNameById(Long materialId, Long currentDeptId) {
        // fixme 临时解决空指针
        var entity = getMaterialInfoById(materialId, currentDeptId);
        if (Objects.isNull(entity)) {
            return "已删除";
        }
        return entity.getMaterialName();
    }

