    public boolean legalRecipeCode(String recipeCode, Long currentDeptId, Long recipeId) {
        TbCastingChargeRecipe recipe = new TbCastingChargeRecipe();
        recipe.setRecipeNum(recipeCode);
        recipe.setTenantId(currentDeptId);
        recipe.setHistoryFlag(0);
        LambdaQueryWrapper<TbCastingChargeRecipe> wrapper = Wrappers.lambdaQuery(recipe);
        if (recipeId != null) {
            wrapper.ne(TbCastingChargeRecipe::getRecipeId, recipeId);
        }
        return StringUtils.isNotBlank(recipeCode) &&
            tbCastingChargeRecipeMapper.selectCount(wrapper) == 0;
    }

