private MaterialPoolElementDetailVo toElementDetailVo(TbMaterialPool pool, List<TbMaterialPoolItem> items,
                                                      Map<Long, BigDecimal> latestUnitPriceMap,
                                                      Map<Long, List<TbMaterialElementContent>> elementMap) {
    List<TbMaterialPoolItem> sortedItems = sortedItems(items);
    List<MaterialPoolMaterialElementVo> materialVos = sortedItems.stream()
        .map(item -> toMaterialElementVo(
            item,
            latestUnitPriceMap,
            elementMap.getOrDefault(item.getMaterialId(), Collections.emptyList())
        ))
        .collect(Collectors.toList());

    MaterialPoolElementDetailVo vo = new MaterialPoolElementDetailVo();
    vo.setId(pool.getId());
    vo.setPoolName(pool.getPoolName());
    vo.setMaxMaterialTypeCount(pool.getMaxMaterialTypeCount());
    vo.setRemark(pool.getRemark());
    vo.setMaterialTotalQuantity(sumMaterialQuantity(sortedItems));
    vo.setMaterials(materialVos);
    vo.setSummaryElements(buildSummaryElements(sortedItems, elementMap));
    return vo;
}

private MaterialPoolMaterialElementVo toMaterialElementVo(TbMaterialPoolItem item,
                                                          Map<Long, BigDecimal> latestUnitPriceMap,
                                                          List<TbMaterialElementContent> elements) {
    MaterialPoolMaterialElementVo vo = new MaterialPoolMaterialElementVo();
    vo.setMaterialId(item.getMaterialId());
    vo.setMaterialCode(item.getMaterialCode());
    vo.setMaterialName(item.getMaterialName());
    vo.setMaterialAlias(item.getMaterialAlias());
    vo.setMaterialQuantity(item.getMaterialQuantity());
    vo.setLatestUnitPrice(latestUnitPriceMap.get(item.getMaterialId()));
    vo.setFeedingAccuracy(item.getFeedingAccuracy());
    vo.setSortNum(item.getSortNum());
    vo.setElements(elements.stream()
        .map(this::toElementVo)
        .collect(Collectors.toList()));
    return vo;
}

private List<MaterialPoolElementVo> buildSummaryElements(List<TbMaterialPoolItem> items,
                                                         Map<Long, List<TbMaterialElementContent>> elementMap) {
    Map<String, ElementSummaryAccumulator> accumulatorMap = new LinkedHashMap<>();
    for (TbMaterialPoolItem item : items) {
        BigDecimal materialQuantity = item.getMaterialQuantity();
        if (materialQuantity == null || materialQuantity.compareTo(BigDecimal.ZERO) <= 0) {
            continue;
        }
        List<TbMaterialElementContent> elements = elementMap.getOrDefault(
            item.getMaterialId(),
            Collections.emptyList()
        );
        for (TbMaterialElementContent element : elements) {
            if (StringUtils.isBlank(element.getElementName())) {
                continue;
            }
            ElementSummaryAccumulator accumulator = accumulatorMap.computeIfAbsent(
                element.getElementName(),
                ElementSummaryAccumulator::new
            );
            accumulator.setElementChineseNameIfAbsent(element.getElementChineseName());
            accumulator.addMin(element.getContentMin(), materialQuantity);
            accumulator.addMax(element.getContentMax(), materialQuantity);
            accumulator.addFixed(element.getContentFixed(), materialQuantity);
        }
    }
    return accumulatorMap.values().stream()
        .map(ElementSummaryAccumulator::toVo)
        .collect(Collectors.toList());
}

private MaterialPoolElementVo toElementVo(TbMaterialElementContent element) {
    MaterialPoolElementVo vo = new MaterialPoolElementVo();
    List<TbMaterialPoolItem> items = listItemsByPoolId(tenantId, poolId);
    Map<Long, BigDecimal> latestUnitPriceMap = queryLatestUnitPriceMap(tenantId, items);
    Map<Long, List<TbMaterialElementContent>> elementMap = queryMaterialElementMap(tenantId, items);
    return toElementDetailVo(pool, items, latestUnitPriceMap, elementMap);
}

/**
 * 解析试算选中的原料库物料；同一物料出现在多个池时只返回一次，并保持页面选择顺序。
 */
public List<MaterialPoolMaterialElementVo> getCalculationMaterials(List<Long> materialIds, Long tenantId) {
    checkTenantId(tenantId);
    List<Long> selectedIds = (materialIds == null ? Collections.<Long>emptyList() : materialIds).stream()
        .filter(Objects::nonNull)
        .distinct()
        .collect(Collectors.toList());
    if (selectedIds.isEmpty()) {
        return Collections.emptyList();
    }

    // 原料库是计算白名单；这里只读取池配置、成分和单价，不读取库存数量或库存状态。
    List<TbMaterialPoolItem> items = tbMaterialPoolItemMapper.selectList(
        Wrappers.<TbMaterialPoolItem>lambdaQuery()
            .eq(TbMaterialPoolItem::getTenantId, tenantId)
            .in(TbMaterialPoolItem::getMaterialId, selectedIds)
            .orderByAsc(TbMaterialPoolItem::getPoolId)
            .orderByAsc(TbMaterialPoolItem::getSortNum)
            .orderByAsc(TbMaterialPoolItem::getId));
    Map<Long, TbMaterialPoolItem> itemByMaterialId = items.stream().collect(Collectors.toMap(
