private MaterialPoolElementDetailVo toElementDetailVo(TbMaterialPool pool, List<TbMaterialPoolItem> items,
                                                      Map<Long, BigDecimal> latestUnitPriceMap,
                                                      Map<Long, List<TbMaterialElementContent>> elementMap) {
    List<TbMaterialPoolItem> sortedItems = sortedItems(items);
    List<MaterialPoolMaterialElementVo> materialVos = sortedItems.stream()
        .map(item -> toMaterialElementVo(
            item,
            latestUnitPriceMap,
            elementMap.getOrDefault(item.getMaterialId(), Collections.emptyList())
        ))
        .collect(Collectors.toList());

    MaterialPoolElementDetailVo vo = new MaterialPoolElementDetailVo();
    vo.setId(pool.getId());
    vo.setPoolName(pool.getPoolName());
    vo.setMaxMaterialTypeCount(pool.getMaxMaterialTypeCount());
    vo.setRemark(pool.getRemark());
    vo.setMaterialTotalQuantity(sumMaterialQuantity(sortedItems));
    vo.setMaterials(materialVos);
    vo.setSummaryElements(buildSummaryElements(sortedItems, elementMap));
    return vo;
}

