    MaterialPoolMaterialElementVo vo = new MaterialPoolMaterialElementVo();
    vo.setMaterialId(item.getMaterialId());
    vo.setMaterialCode(item.getMaterialCode());
    vo.setMaterialName(item.getMaterialName());
    vo.setMaterialAlias(item.getMaterialAlias());
    vo.setMaterialQuantity(item.getMaterialQuantity());
    vo.setLatestUnitPrice(latestUnitPriceMap.get(item.getMaterialId()));
    vo.setFeedingAccuracy(item.getFeedingAccuracy());
    vo.setSortNum(item.getSortNum());
    vo.setElements(elements.stream()
        .map(this::toElementVo)
        .collect(Collectors.toList()));
    return vo;
}

private List<MaterialPoolElementVo> buildSummaryElements(List<TbMaterialPoolItem> items,
                                                         Map<Long, List<TbMaterialElementContent>> elementMap) {
    Map<String, ElementSummaryAccumulator> accumulatorMap = new LinkedHashMap<>();
    for (TbMaterialPoolItem item : items) {
        BigDecimal materialQuantity = item.getMaterialQuantity();
        if (materialQuantity == null || materialQuantity.compareTo(BigDecimal.ZERO) <= 0) {
            continue;
        }
        List<TbMaterialElementContent> elements = elementMap.getOrDefault(
            item.getMaterialId(),
            Collections.emptyList()
        );
        for (TbMaterialElementContent element : elements) {
            if (StringUtils.isBlank(element.getElementName())) {
                continue;
            }
            ElementSummaryAccumulator accumulator = accumulatorMap.computeIfAbsent(
                element.getElementName(),
                ElementSummaryAccumulator::new
            );
            accumulator.setElementChineseNameIfAbsent(element.getElementChineseName());
            accumulator.addMin(element.getContentMin(), materialQuantity);
            accumulator.addMax(element.getContentMax(), materialQuantity);
            accumulator.addFixed(element.getContentFixed(), materialQuantity);
        }
    }
    return accumulatorMap.values().stream()
        .map(ElementSummaryAccumulator::toVo)
        .collect(Collectors.toList());
}

