/**
 * 解析试算选中的原料库物料；同一物料出现在多个池时只返回一次，并保持页面选择顺序。
 */
public List<MaterialPoolMaterialElementVo> getCalculationMaterials(List<Long> materialIds, Long tenantId) {
    checkTenantId(tenantId);
    List<Long> selectedIds = (materialIds == null ? Collections.<Long>emptyList() : materialIds).stream()
        .filter(Objects::nonNull)
        .distinct()
        .collect(Collectors.toList());
    if (selectedIds.isEmpty()) {
        return Collections.emptyList();
    }

    // 原料库是计算白名单；这里只读取池配置、成分和单价，不读取库存数量或库存状态。
    List<TbMaterialPoolItem> items = tbMaterialPoolItemMapper.selectList(
        Wrappers.<TbMaterialPoolItem>lambdaQuery()
            .eq(TbMaterialPoolItem::getTenantId, tenantId)
            .in(TbMaterialPoolItem::getMaterialId, selectedIds)
            .orderByAsc(TbMaterialPoolItem::getPoolId)
            .orderByAsc(TbMaterialPoolItem::getSortNum)
            .orderByAsc(TbMaterialPoolItem::getId));
    Map<Long, TbMaterialPoolItem> itemByMaterialId = items.stream().collect(Collectors.toMap(
        TbMaterialPoolItem::getMaterialId, Function.identity(), (left, right) -> left, LinkedHashMap::new));
    Map<Long, BigDecimal> latestUnitPriceMap = queryLatestUnitPriceMap(tenantId, items);
    Map<Long, List<TbMaterialElementContent>> elementMap = queryMaterialElementMap(tenantId, items);

    return selectedIds.stream()
        .map(itemByMaterialId::get)
        .filter(Objects::nonNull)
        .map(item -> toMaterialElementVo(item, latestUnitPriceMap,
            elementMap.getOrDefault(item.getMaterialId(), Collections.emptyList())))
        .collect(Collectors.toList());
}

public MaterialPoolItemDetailVo getItemDetail(Long itemId) {
    Long tenantId = getCurrentTenantId();
    TbMaterialPoolItem item = getItemOrThrow(itemId, tenantId);
    Map<Long, BigDecimal> latestUnitPriceMap = queryLatestUnitPriceMap(
        tenantId,
        Collections.singletonList(item)
    );
    Map<Long, List<TbMaterialElementContent>> elementMap = queryMaterialElementMap(
        tenantId,
        Collections.singletonList(item)
    );
    return toItemDetailVo(
        item,
        latestUnitPriceMap,
        elementMap.getOrDefault(item.getMaterialId(), Collections.emptyList())
    );
}

