package com.allthinkstars.framework.iot.erp.datasource.entities;

import com.allthinkstars.framework.core.base.DbSchemas;
import com.baomidou.mybatisplus.annotation.TableLogic;
import com.baomidou.mybatisplus.annotation.TableName;
