 */
@Data
@TableName(value = "tb_material_element_content", schema = DbSchemas.ATS_ERP)
public class TbMaterialElementContent implements Serializable {

    private static final long serialVersionUID = -47180373693414402L;

    private Long id;
    /**
     * 物料id
     */
    @NotNull
    @ApiModelProperty(value = "物料id",required = true)
    private Long materialId;
    /**
     * 元素名
     */
    @NotBlank
    @ApiModelProperty(value = "元素名",required = true )
    private String elementName;
    /**
     * 元素中文名
     */
    @ApiModelProperty("元素中文名")
    private String elementChineseName;
    /**
     * 含量最小值
     */
    @ApiModelProperty("含量最小值")
    private BigDecimal contentMin;
    /**
     * 含量最大值
     */
    @ApiModelProperty("含量最大值")
    private BigDecimal contentMax;
    /**
