    public IPage<MaterialPoolVo> page(PageQuery pageQuery, MaterialPoolPageDto dto) {
        Long tenantId = getCurrentTenantId();
        MaterialPoolPageDto query = OptionalDto.of(dto);

        LambdaQueryWrapper<TbMaterialPool> wrapper = Wrappers.<TbMaterialPool>lambdaQuery()
            .eq(TbMaterialPool::getTenantId, tenantId)
            .like(StringUtils.isNotBlank(query.getPoolName()),
                TbMaterialPool::getPoolName,
                StringUtils.trim(query.getPoolName()))
            .orderByDesc(TbMaterialPool::getCreateTime)
            .orderByDesc(TbMaterialPool::getId);

        if (StringUtils.isNotBlank(query.getMaterialKeyword())) {
            List<Long> poolIds = queryPoolIdsByMaterialKeyword(tenantId, query.getMaterialKeyword());
            if (CollectionUtils.isEmpty(poolIds)) {
                return emptyPage(pageQuery);
            }
            wrapper.in(TbMaterialPool::getId, poolIds);
        }

        IPage<TbMaterialPool> poolPage = tbMaterialPoolMapper.selectPage(pageQuery.build(), wrapper);
        return PageUtils.toPage(poolPage, buildPoolVos(tenantId, poolPage.getRecords()));
    }

    public IPage<MaterialPoolPageVo> pageSummary(PageQuery pageQuery, MaterialPoolPageDto dto) {
        Long tenantId = getCurrentTenantId();
