package com.allthinkstars.framework.datasource.tenant;

import com.allthinkstars.framework.core.base.DbSchemas;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.jdbc.DataSourceBuilder;
import org.springframework.stereotype.Component;

import javax.sql.DataSource;
import java.io.Closeable;
import java.sql.Connection;
import java.sql.Statement;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

/** 按租户懒加载和缓存客户数据库连接池。 */
@Slf4j
@Component
public class TenantDataSourceRegistry {

    private static final String ACTIVE = "0";
    private static final long BINDING_CACHE_MILLIS = 30_000L;
    private final TenantDataSourceConfigLoader configLoader;
    private final Map<TenantDataSourceKey, DataSourceHolder> holders = new ConcurrentHashMap<>();
    private final Map<Long, BindingCacheEntry> bindingCache = new ConcurrentHashMap<>();
    private final Map<Long, ReentrantLock> locks = new ConcurrentHashMap<>();

    public TenantDataSourceRegistry(TenantDataSourceConfigLoader configLoader) {
        this.configLoader = configLoader;
    }

    public DataSource getDataSource(Long tenantId, String logicalName, DataSource fallback) {
        TenantDataSourceBinding binding = loadBinding(tenantId);
        if (binding == null) {
            return fallback;
        }
        validateBinding(binding);

        TenantDataSourceKey key = new TenantDataSourceKey(tenantId, logicalName);
        DataSourceHolder current = holders.get(key);
        if (current != null && sameVersion(current, binding)) {
            return current.dataSource;
        }

        ReentrantLock lock = locks.computeIfAbsent(tenantId, ignored -> new ReentrantLock());
        lock.lock();
        try {
            current = holders.get(key);
            if (current != null && sameVersion(current, binding)) {
                return current.dataSource;
            }
            DataSource created = createAndValidate(binding, logicalName);
            DataSourceHolder replacement = new DataSourceHolder(binding.getConnectionConfigId(),
                binding.getConfigVersion(), created);
            holders.put(key, replacement);
            close(current == null ? null : current.dataSource);
            log.info("租户数据库连接池已加载，tenantId={}, connectionConfigId={}",
                tenantId, binding.getConnectionConfigId());
            return created;
        } finally {
            lock.unlock();
        }
    }

    public void invalidate(Long tenantId) {
        bindingCache.remove(tenantId);
        holders.entrySet().removeIf(entry -> {
            if (!entry.getKey().tenantId.equals(tenantId)) {
                return false;
            }
            close(entry.getValue().dataSource);
            return true;
        });
    }

    /** 配置中心或 PM 修改绑定后调用，立即使租户连接池失效。 */
    public void refreshTenant(Long tenantId) {
        invalidate(tenantId);
    }

    public void closeAll() {
        holders.values().forEach(holder -> close(holder.dataSource));
        holders.clear();
        bindingCache.clear();
    }

    private DataSource createAndValidate(TenantDataSourceBinding binding, String logicalName) {
        try {
            DataSourceBuilder<?> builder = DataSourceBuilder.create();
            if (binding.getDriverClassName() != null) {
                builder.driverClassName(binding.getDriverClassName());
            }
            DataSource dataSource = builder.url(resolveJdbcUrl(binding.getJdbcUrl(), logicalName))
                .username(binding.getUsername())
                .password(binding.getPassword())
                .build();
            try (Connection connection = dataSource.getConnection();
                 Statement statement = connection.createStatement()) {
                statement.execute("SELECT 1");
            }
            return dataSource;
        } catch (Exception e) {
            throw new TenantDataSourceException("客户数据库连接失败，tenantId=" + binding.getTenantId(), e);
        }
    }

    private TenantDataSourceBinding loadBinding(Long tenantId) {
        long now = System.currentTimeMillis();
        BindingCacheEntry cached = bindingCache.get(tenantId);
        if (cached != null && now - cached.loadedAt < BINDING_CACHE_MILLIS) {
            return cached.binding;
        }
        TenantDataSourceBinding binding = configLoader.load(tenantId);
        bindingCache.put(tenantId, new BindingCacheEntry(binding, now));
        return binding;
    }

    private void validateBinding(TenantDataSourceBinding binding) {
        if (!ACTIVE.equals(binding.getBindingStatus())) {
            throw new TenantDataSourceException("租户数据库绑定未生效，tenantId=" + binding.getTenantId());
        }
        if (binding.getConnectionConfigId() == null || !ACTIVE.equals(binding.getConnectionStatus())) {
            throw new TenantDataSourceException("租户数据库连接配置不可用，tenantId=" + binding.getTenantId());
        }
        if (isBlank(binding.getJdbcUrl()) || isBlank(binding.getUsername())
            || binding.getPassword() == null) {
            throw new TenantDataSourceException("租户数据库连接配置不完整，tenantId=" + binding.getTenantId());
        }
    }

    private boolean sameVersion(DataSourceHolder holder, TenantDataSourceBinding binding) {
        return holder.connectionConfigId.equals(binding.getConnectionConfigId())
            && (holder.configVersion == null ? binding.getConfigVersion() == null
            : holder.configVersion.equals(binding.getConfigVersion()));
    }

    private static boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    /**
     * 客户侧通常与云端保持相同的数据库命名约定，仅连接主机和端口不同。
     * 绑定记录保存一个连接入口，实际创建连接池时按逻辑数据源切换默认 schema。
     */
    private static String resolveJdbcUrl(String jdbcUrl, String logicalName) {
        String schema = schemaFor(logicalName);
        if (schema == null || isBlank(jdbcUrl)) {
            return jdbcUrl;
        }
        int queryIndex = jdbcUrl.indexOf('?');
        String query = queryIndex >= 0 ? jdbcUrl.substring(queryIndex) : "";
        String base = queryIndex >= 0 ? jdbcUrl.substring(0, queryIndex) : jdbcUrl;
        int slashIndex = base.lastIndexOf('/');
        if (slashIndex < "jdbc:mysql://".length()) {
            return jdbcUrl;
        }
        return base.substring(0, slashIndex + 1) + schema + query;
    }

    private static String schemaFor(String logicalName) {
        Map<String, String> schemas = new HashMap<>();
        schemas.put("master", DbSchemas.ATSI_IOT_ADMIN);
        schemas.put("atsiErp", DbSchemas.ATS_ERP);
        schemas.put("atsIot", DbSchemas.ATS_IOT);
        schemas.put("iotData", DbSchemas.ATSI_IOT_DATA);
        return schemas.get(logicalName);
    }

    private static void close(Object target) {
        if (target instanceof Closeable) {
            try {
                ((Closeable) target).close();
            } catch (Exception e) {
                log.warn("关闭租户数据库连接池失败", e);
            }
        }
    }

    private static final class DataSourceHolder {
        private final Long connectionConfigId;
        private final Integer configVersion;
        private final DataSource dataSource;

        private DataSourceHolder(Long connectionConfigId, Integer configVersion, DataSource dataSource) {
            this.connectionConfigId = connectionConfigId;
            this.configVersion = configVersion;
            this.dataSource = dataSource;
        }
    }

    private static final class TenantDataSourceKey {
        private final Long tenantId;
        private final String logicalName;

        private TenantDataSourceKey(Long tenantId, String logicalName) {
            this.tenantId = tenantId;
            this.logicalName = logicalName;
        }

        @Override
        public boolean equals(Object other) {
            if (this == other) {
                return true;
            }
            if (!(other instanceof TenantDataSourceKey)) {
                return false;
            }
            TenantDataSourceKey that = (TenantDataSourceKey) other;
            return tenantId.equals(that.tenantId) && java.util.Objects.equals(logicalName, that.logicalName);
        }

        @Override
        public int hashCode() {
            return java.util.Objects.hash(tenantId, logicalName);
        }
    }

    private static final class BindingCacheEntry {
        private final TenantDataSourceBinding binding;
        private final long loadedAt;

        private BindingCacheEntry(TenantDataSourceBinding binding, long loadedAt) {
            this.binding = binding;
            this.loadedAt = loadedAt;
        }
    }
}
