package com.allthinkstars.framework.datasource.tenant;

import com.baomidou.dynamic.datasource.DynamicRoutingDataSource;
import lombok.extern.slf4j.Slf4j;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

import javax.sql.DataSource;
import java.util.List;
import java.util.Map;

/**
 * 从固定 master 数据源加载租户数据库绑定配置，避免配置表被再次路由到客户库。
 */
@Slf4j
@Component
public class TenantDataSourceConfigLoader {

    private static final String ADMIN_SCHEMA = "atsi_iot_admin";
    private final JdbcTemplate masterJdbcTemplate;

    public TenantDataSourceConfigLoader(DataSource dataSource) {
        DynamicRoutingDataSource dynamicRoutingDataSource = (DynamicRoutingDataSource) dataSource;
        DataSource master = dynamicRoutingDataSource.getDataSource("master");
        if (master == null) {
            throw new TenantDataSourceException("未找到 master 数据源，无法加载租户数据库配置");
        }
        this.masterJdbcTemplate = new JdbcTemplate(master);
    }

    public TenantDataSourceBinding load(Long tenantId) {
        String sql = "select b.tenant_id, b.connection_config_id, b.status binding_status, "
            + "c.status connection_status, c.database_type, c.driver_class_name, c.jdbc_url, "
            + "c.username, c.password, c.config_version "
            + "from " + ADMIN_SCHEMA + ".tb_database_tenant_data_source_binding b "
            + "left join " + ADMIN_SCHEMA + ".tb_database_connection_config c "
            + "on c.id = b.connection_config_id where b.tenant_id = ? limit 1";
        List<Map<String, Object>> rows = masterJdbcTemplate.queryForList(sql, tenantId);
        if (rows.isEmpty()) {
            return null;
        }
        Map<String, Object> row = rows.get(0);
        return TenantDataSourceBinding.builder()
            .tenantId(longValue(row.get("tenant_id")))
            .connectionConfigId(longValue(row.get("connection_config_id")))
            .bindingStatus(stringValue(row.get("binding_status")))
            .connectionStatus(stringValue(row.get("connection_status")))
            .databaseType(stringValue(row.get("database_type")))
            .driverClassName(stringValue(row.get("driver_class_name")))
            .jdbcUrl(stringValue(row.get("jdbc_url")))
            .username(stringValue(row.get("username")))
            .password(stringValue(row.get("password")))
            .configVersion(intValue(row.get("config_version")))
            .build();
    }

    /** 查询所有已生效的客户数据库绑定，供跨租户后台任务逐库执行。 */
    public List<Long> listActiveTenantIds() {
        String sql = "select distinct b.tenant_id "
            + "from " + ADMIN_SCHEMA + ".tb_database_tenant_data_source_binding b "
            + "inner join " + ADMIN_SCHEMA + ".tb_database_connection_config c "
            + "on c.id = b.connection_config_id "
            + "where b.status = '0' and c.status = '0' order by b.tenant_id";
        return masterJdbcTemplate.query(sql, (resultSet, rowNum) -> resultSet.getLong("tenant_id"));
    }

    /**
     * 从云端控制库解析设备所属工厂。
     *
     * <p>租户数据源尚未选定时不能调用普通 Mapper，否则 master 也支持租户路由后会形成递归。</p>
     */
    public Long findTenantIdByDevice(Long deviceInternalId) {
        String sql = "select dept_id from " + ADMIN_SCHEMA
            + ".tb_device_default_info where device_internal_id = ? limit 1";
        List<Long> tenantIds = masterJdbcTemplate.query(sql, (resultSet, rowNum) -> {
            long tenantId = resultSet.getLong("dept_id");
            return resultSet.wasNull() ? null : tenantId;
        }, deviceInternalId);
        if (tenantIds.isEmpty() || tenantIds.get(0) == null) {
            throw new TenantDataSourceException("设备未绑定工厂，deviceInternalId=" + deviceInternalId);
        }
        return tenantIds.get(0);
    }

    private static String stringValue(Object value) {
        return value == null ? null : String.valueOf(value);
    }

    private static Long longValue(Object value) {
        return value == null ? null : ((Number) value).longValue();
    }

    private static Integer intValue(Object value) {
        return value == null ? null : ((Number) value).intValue();
    }
}
