    @Override
    public boolean addMaterialElementContent(AddMaterialElementContent param) {
        Long materialId = param.getMaterialId();
        TbMaterialInfo materialInfo = tbMaterialInfoMapper.selectById(materialId);
        if (materialInfo == null) {
            throw new ServiceException("物料信息不存在");
        }

        // 新增入口先按炉料和元素符号校验，避免绕过前端后写入重复的质量分数记录。
        Long elementCount = tbMaterialElementContentMapper.selectCount(Wrappers.<TbMaterialElementContent>lambdaQuery()
            .eq(TbMaterialElementContent::getMaterialId, materialId)
            .eq(TbMaterialElementContent::getElementName, StringUtils.trim(param.getElementName())));
        if (elementCount > 0) {
            throw new ServiceException("炉料元素成分不能重复");
        }

        TbMaterialElementContent tbMaterialElementContent = new TbMaterialElementContent();
        tbMaterialElementContent.setMaterialId(param.getMaterialId());
        tbMaterialElementContent.setElementName(StringUtils.trim(param.getElementName()));
        tbMaterialElementContent.setElementChineseName(param.getElementChineseName());
        tbMaterialElementContent.setContentMin(param.getContentMin());
        tbMaterialElementContent.setContentMax(param.getContentMax());
        tbMaterialElementContent.setBurningRate(param.getBurningRate());
        tbMaterialElementContent.setContentFixed(param.getContentFixed());
        tbMaterialElementContentMapper.insert(tbMaterialElementContent);
        return true;
    }


    @Override
    public boolean delMaterialElementContent(Long id) {
        TbMaterialElementContent tbMaterialElementContent = tbMaterialElementContentMapper.selectById(id);
        if (tbMaterialElementContent == null) {
            throw new ServiceException("物料元素详情不存在");
        }
        return tbMaterialElementContentMapper.deleteById(tbMaterialElementContent) > 0;
    }



    @Override
    public boolean editMaterialAlias(EditMaterialAliasParam param) {
        Long materialId = param.getMaterialId();
        TbMaterialInfo tbMaterialInfo = tbMaterialInfoMapper.selectById(materialId);
        if (tbMaterialInfo == null) {
            throw new ServiceException("物料不存在");
        }
        if (ArrayUtils.isEmpty(param.getMaterialAlias())) {
            tbMaterialInfo.setMaterialAlias("");
    }

    /**
     * 非空参考价必须能够换算为元/kg，避免单位或每米重量缺失时把错误口径写入主数据。
     */
    private BigDecimal toCanonicalReferencePrice(BigDecimal referencePrice,
                                                 String unit,
                                                 BigDecimal weightPerLength) {
        BigDecimal canonicalPrice = materialPriceService.toCanonicalReferencePrice(
            referencePrice, unit, weightPerLength);
        if (referencePrice != null && canonicalPrice == null) {
            throw new ServiceException("参考价必须为非负数且可换算为元/kg，请检查物料单位和每米重量");
        }
        return canonicalPrice;
    }

    /**
     * 校验单次炉料编辑中的元素符号唯一，历史查询链路不调用此方法。
     */
    private void validateUniqueElementNames(List<TbMaterialElementContent> elementContents) {
        if (CollectionUtils.isEmpty(elementContents)) {
            return;
        }

        // 元素周期表符号区分大小写；仅归一化首尾空白，避免录入空格绕过重复校验。
        Set<String> elementNames = Sets.newHashSet();
        boolean containsDuplicate = elementContents.stream()
            .map(TbMaterialElementContent::getElementName)
            .filter(StringUtils::isNotBlank)
            .map(StringUtils::trim)
            .anyMatch(elementName -> !elementNames.add(elementName));
        if (containsDuplicate) {
            throw new ServiceException("炉料元素成分不能重复");
        }
    }

